"""Durable CLI/direct-entry boundaries with generated bytes and fake ASR only."""
from contextlib import contextmanager
import json
import os
from pathlib import Path
import sys
import threading

import pytest

from file_lock import FileLock
from scripts import audio_segments as audio
from scripts import transcript_results as results
from scripts import transcribe_backfill as tb


TAG = "entry_synthetic"
DAY = "2000-01-01"


@pytest.fixture
def data(tmp_path, monkeypatch):
    tb._release_run_lock()
    monkeypatch.setattr(tb, "DATA", tmp_path)
    monkeypatch.setattr(tb, "CUSTOMER", None)
    monkeypatch.delenv("DY_CUSTOMER_CONTEXT", raising=False)
    monkeypatch.setattr(sys, "argv", ["transcribe_backfill", "--all", "--model", "entry-fake-A"])
    yield tmp_path
    tb._release_run_lock()


def closed_source(data):
    folder = data / f"audio_{TAG}_{DAY}"
    folder.mkdir(exist_ok=True)
    number, path = audio.reserve_segment(data, folder)
    with path.open("xb") as stream:
        stream.write(b"generated-audio-byte-pattern" * 256)
        stream.flush()
        os.fsync(stream.fileno())
    audio.publish_closed(data, folder, path, number, 100.0, 101.0)
    return folder, path


def speech_path(data):
    return data / f"speech_{TAG}_{DAY}.jsonl"


def fake_asr(monkeypatch, recognize=None):
    calls = {"model": 0, "ffmpeg": 0, "recognize": 0}
    marker = object()
    def load(*_args):
        calls["model"] += 1
        return marker
    def ffmpeg():
        calls["ffmpeg"] += 1
        return None
    def transcribe(model, path, prompt):
        assert model is marker
        calls["recognize"] += 1
        if recognize is not None:
            return recognize(path)
        return [{"start": 0, "end": 1, "text": "generated speech"}], 1.0
    monkeypatch.setattr(tb, "load_model", load)
    monkeypatch.setattr(tb, "find_ffmpeg", ffmpeg)
    monkeypatch.setattr(tb, "transcribe_audio", transcribe)
    return calls


def prohibit_model(monkeypatch):
    monkeypatch.setattr(tb, "load_model", lambda *_a: pytest.fail("unneeded model load"))
    monkeypatch.setattr(tb, "find_ffmpeg", lambda: pytest.fail("unneeded ffmpeg discovery"))
    monkeypatch.setattr(tb, "transcribe_audio", lambda *_a: pytest.fail("unneeded recognition"))


@contextmanager
def another_writer(data):
    entered, release = threading.Event(), threading.Event()
    errors = []
    def hold():
        lock = FileLock(data / ".transcribe.run", timeout=0)
        try:
            assert lock.acquire(blocking=False)
            entered.set()
            assert release.wait(5), "test failed to release its synthetic writer"
        except BaseException as error:
            errors.append(error)
            entered.set()
        finally:
            lock.release()
    worker = threading.Thread(target=hold)
    worker.start()
    try:
        assert entered.wait(2) and errors == []
        yield
    finally:
        release.set()
        worker.join(2)
        assert not worker.is_alive() and errors == []


def test_completed_result_survives_model_name_change_without_loading(data, monkeypatch):
    folder, source = closed_source(data)
    calls = fake_asr(monkeypatch)
    assert tb.main() == 0
    assert calls["model"] == calls["recognize"] == 1
    before = speech_path(data).read_bytes()
    first = results.validate_success(data, folder, source.name)
    assert first["result_committed"] and first["projection_ready"] and first["cleanup_eligible"]
    monkeypatch.setattr(sys, "argv", ["transcribe_backfill", "--all", "--model", "new-install/model-B"])
    prohibit_model(monkeypatch)
    assert tb.main() == 0
    assert speech_path(data).read_bytes() == before
    assert results.validate_success(data, folder, source.name)["generation"] == first["generation"]


def test_projection_recovery_does_not_load_model_or_repeat_speech(data, monkeypatch):
    folder, source = closed_source(data)
    fake_asr(monkeypatch)
    assert tb.main() == 0
    before = speech_path(data).read_bytes()
    generation = results.validate_success(data, folder, source.name)["generation"]
    speech_path(data).write_bytes(b'{"generated-partial-line":')
    damaged = results.validate_success(data, folder, source.name)
    assert damaged["result_committed"] and not damaged["projection_ready"]
    assert not damaged["cleanup_eligible"]
    prohibit_model(monkeypatch)
    assert tb.main() == 0
    assert speech_path(data).read_bytes() == before
    recovered = results.validate_success(data, folder, source.name)
    assert recovered["generation"] == generation and recovered["cleanup_eligible"]


def test_cli_busy_is_distinct_and_never_loads_model(data, monkeypatch):
    closed_source(data)
    prohibit_model(monkeypatch)
    with another_writer(data):
        assert tb.main() == 3
    assert not speech_path(data).exists()
    assert tb._run_lock is None


def test_direct_directory_entry_cooperates_with_the_same_writer_lock(data, monkeypatch):
    folder, source = closed_source(data)
    monkeypatch.setattr(tb, "transcribe_audio", lambda *_a: pytest.fail("direct entry bypassed global writer"))
    with another_writer(data):
        with pytest.raises(Exception) as caught:
            tb.transcribe_dir(object(), folder, None, False, "entry-fake")
    assert getattr(caught.value, "reason", None) == "busy" or "busy" in str(caught.value).lower()
    assert not speech_path(data).exists()
    assert not results.validate_success(data, folder, source.name)["result_committed"]


def test_unconfirmed_open_source_is_not_a_completed_day(data, monkeypatch):
    folder = data / f"audio_{TAG}_{DAY}"
    folder.mkdir()
    _number, source = audio.reserve_segment(data, folder)
    with source.open("xb") as writer:
        writer.write(b"synthetic-still-writing" * 256)
        writer.flush()
        prohibit_model(monkeypatch)
        assert tb.main() != 0
        assert not speech_path(data).exists()
    assert source.exists()
    assert not results.validate_success(data, folder, source.name)["cleanup_eligible"]


def test_without_customer_environment_uses_durable_facts_and_never_legacy_append(data, monkeypatch):
    folder, source = closed_source(data)
    fake_asr(monkeypatch)
    assert "DY_CUSTOMER_CONTEXT" not in os.environ and tb.CUSTOMER is None
    assert tb.main() == 0
    assert not (folder / ".transcribed.json").exists()
    status = results.validate_success(data, folder, source.name)
    assert status["result_committed"] and status["projection_ready"] and status["cleanup_eligible"]
    rows = [json.loads(line) for line in speech_path(data).read_text(encoding="utf-8").splitlines()]
    assert len(rows) == 1 and rows[0]["seg"] == source.stem and rows[0]["off"] == 0


def test_unknown_legacy_speech_is_preserved_and_not_granted_cleanup(data, monkeypatch):
    folder, source = closed_source(data)
    previous = b'{"text":"generated legacy record","legacy":true}\n'
    speech_path(data).write_bytes(previous)
    fake_asr(monkeypatch)
    assert tb.main() != 0
    assert speech_path(data).read_bytes() == previous and source.exists()
    assert not results.validate_success(data, folder, source.name)["cleanup_eligible"]


def test_source_replaced_during_recognition_cannot_commit(data, monkeypatch):
    folder, source = closed_source(data)
    original = source.stat()
    def replace_same_size_and_timestamp(path):
        path.write_bytes(b"X" * original.st_size)
        os.utime(path, ns=(original.st_atime_ns, original.st_mtime_ns))
        return [{"start": 0, "end": 1, "text": "must not be committed"}], 1.0
    fake_asr(monkeypatch, replace_same_size_and_timestamp)
    assert tb.main() != 0
    assert source.stat().st_size == original.st_size and source.stat().st_mtime_ns == original.st_mtime_ns
    assert not results.validate_success(data, folder, source.name)["result_committed"]
    assert not speech_path(data).exists()


@pytest.mark.parametrize("seconds,expected_success", [(1.0, True), (0.0, False)])
def test_decoded_empty_voice_and_zero_length_decode_are_distinct(data, monkeypatch, seconds, expected_success):
    folder, source = closed_source(data)
    fake_asr(monkeypatch, lambda _path: ([], seconds))
    code = tb.main()
    status = results.validate_success(data, folder, source.name)
    if expected_success:
        assert code == 0 and status["cleanup_eligible"]
        assert speech_path(data).read_bytes() == b""
    else:
        assert code != 0 and not status["result_committed"] and not status["cleanup_eligible"]
        assert not speech_path(data).exists()
